(() => {
const {app,configured,sb,S,esc,nl,token,dateLong,dateShort,diffLabel,statusLabel,statusClass,toast,fail,copyText,modal,cleanupAll,cleanupBoard,cleanupLive,studentLink,configScreen,avg,shuffle}=window.MR;
const {mountBoard,mountSnapshot}=window.MathroomBoard;

async function ensureTeacher(){
  const {data:{user}}=await sb.auth.getUser(); if(!user||user.is_anonymous)return null;
  await sb.from('teachers').upsert({id:user.id},{onConflict:'id'});
  const {data,error}=await sb.from('teachers').select('*').eq('id',user.id).single(); if(error)throw error; return data;
}
async function loadTeacher(){
  const reqs=await Promise.all([
    sb.from('students').select('*').order('created_at'),
    sb.from('topics').select('*').order('grade').order('section').order('title'),
    sb.from('exercises').select('*').order('created_at'),
    sb.from('lessons').select('*,students(name,grade),topics(title)').order('scheduled_at',{ascending:true}),
    sb.from('homeworks').select('*,students(name,grade),topics(title)').order('created_at',{ascending:false}),
    sb.from('tests').select('*,students(name,grade),topics(title)').order('created_at',{ascending:false}),
    sb.from('lesson_board_versions').select('*').order('created_at',{ascending:false})
  ]);
  const err=reqs.find(x=>x.error)?.error;if(err)throw err;
  [S.students,S.topics,S.exercises,S.lessons,S.homeworks,S.tests,S.versions]=reqs.map(x=>x.data||[]);
  if(!S.selectedStudent&&S.students[0])S.selectedStudent=S.students[0].id;
}
async function boot(){
  if(!configured)return configScreen();
  if(S.access)return bootStudent();
  const {data:{session}}=await sb.auth.getSession();
  if(!session||session.user.is_anonymous)return renderAuth();
  S.user=session.user;try{S.teacher=await ensureTeacher();await loadTeacher();renderTeacher()}catch(e){fail(e);renderAuth()}
}
function renderAuth(){
  app.innerHTML=`<div class="center-page"><div class="auth-card"><div class="brand">Mathroom</div><h1>Облачный кабинет</h1><p>GitHub Pages + Supabase</p><form id="loginForm"><div class="field"><label>Email</label><input id="email" type="email" required></div><div class="field"><label>Пароль</label><input id="password" type="password" minlength="6" required></div><div class="actions"><button class="btn primary">Войти</button><button type="button" class="btn" id="register">Создать аккаунт</button></div></form><div id="authMsg" class="small muted" style="margin-top:12px"></div></div></div>`;
  document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();const email=document.getElementById('email').value,password=document.getElementById('password').value;const {data,error}=await sb.auth.signInWithPassword({email,password});if(error)return document.getElementById('authMsg').textContent=error.message;S.user=data.user;S.teacher=await ensureTeacher();await loadTeacher();renderTeacher()};
  document.getElementById('register').onclick=async()=>{const email=document.getElementById('email').value,password=document.getElementById('password').value;const {data,error}=await sb.auth.signUp({email,password});if(error)return document.getElementById('authMsg').textContent=error.message;if(!data.session){document.getElementById('authMsg').textContent='Аккаунт создан. Подтверди email, затем войди.';return}S.user=data.user;S.teacher=await ensureTeacher();await loadTeacher();renderTeacher()};
}

const nav=[['dashboard','Главная'],['schedule','Расписание'],['students','Ученики'],['topics','Темы'],['bank','Банк задач'],['assignments','Задания'],['history','История'],['board','Доска']];
function shell(content,title,sub=''){
  return `<div class="layout"><aside class="sidebar"><div class="brand">Mathroom <span class="cloud-badge">☁ cloud</span></div><nav class="nav">${nav.map(([id,n])=>`<button data-nav="${id}" class="${S.view===id?'active':''}">${n}</button>`).join('')}</nav><div class="sidebar-footer"><button class="btn ghost sm" id="logout">Выйти</button></div></aside><main class="content"><div class="topbar"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div></div>${content}</main></div>`;
}
function bindShell(){
  document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{cleanupAll();S.view=b.dataset.nav;S.topic=null;S.activeLesson=null;renderTeacher()});
  const l=document.getElementById('logout');if(l)l.onclick=async()=>{cleanupAll();await sb.auth.signOut();S.user=S.teacher=null;renderAuth()};
}
function renderTeacher(){
  cleanupAll();
  if(S.view==='students')return renderStudents();
  if(S.view==='profile')return renderStudentProfile(S.selectedStudent);
  if(S.view==='topics')return S.topic?renderTopic():renderTopics();
  if(S.view==='bank')return renderBank();
  if(S.view==='schedule')return renderSchedule();
  if(S.view==='assignments')return renderAssignments();
  if(S.view==='history')return renderHistory();
  if(S.view==='board')return renderBoardPage();
  if(S.view==='lesson')return renderLesson();
  return renderDashboard();
}

function renderDashboard(){
  const now=Date.now(),upcoming=S.lessons.filter(x=>x.status==='assigned'&&x.scheduled_at&&new Date(x.scheduled_at).getTime()>=now).slice(0,5);
  const pending=S.homeworks.filter(x=>x.status==='submitted').length;
  app.innerHTML=shell(`<div class="grid cols4"><div class="card"><div class="muted">Ученики</div><div class="metric">${S.students.length}</div></div><div class="card"><div class="muted">Темы</div><div class="metric">${S.topics.length}</div></div><div class="card"><div class="muted">Задачи</div><div class="metric">${S.exercises.filter(x=>x.kind==='task').length}</div></div><div class="card"><div class="muted">На проверку</div><div class="metric">${pending}</div></div></div><div class="section-title"><h2>Ближайшие уроки</h2></div><div class="list">${upcoming.length?upcoming.map(l=>`<div class="row"><div><h3>${esc(l.students?.name||'Ученик')} · ${esc(l.topics?.title||'Без темы')}</h3><p>${dateLong(l.scheduled_at)} · ${l.duration_minutes} мин</p></div><button class="btn primary sm" data-start="${l.id}">Начать</button></div>`).join(''):'<div class="empty">Добавь первое занятие в разделе «Расписание».</div>'}</div>`,'Кабинет преподавателя','Mathroom Web v3.4 · облачная учебная система');bindShell();
  document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{const l=S.lessons.find(x=>x.id===b.dataset.start);await startLesson(l)});
}

function renderStudents(){
  app.innerHTML=shell(`<div class="form-card"><h2>Добавить ученика</h2><form id="studentForm" class="form-grid"><div class="field"><label>Имя</label><input id="stName" required placeholder="Иван"></div><div class="field"><label>Класс</label><select id="stGrade">${Array.from({length:11},(_,i)=>`<option>${i+1}</option>`).join('')}</select></div><button class="btn primary">Добавить</button></form></div><div class="list">${S.students.length?S.students.map(st=>`<div class="row"><div class="row-main"><h3>${esc(st.name)} · ${st.grade} класс</h3><div class="token-link">${esc(studentLink(st))}</div></div><div class="actions"><button class="btn sm primary" data-profile="${st.id}">Профиль</button><button class="btn sm" data-copy="${st.id}">Копировать</button><button class="btn sm" data-board="${st.id}">Доска</button><button class="btn sm" data-rotate="${st.id}">Новая ссылка</button><button class="btn sm danger" data-delete="${st.id}">Удалить</button></div></div>`).join(''):'<div class="empty">Учеников пока нет.</div>'}</div>`,'Ученики','Персональные ссылки, прогресс и доски');bindShell();
  document.getElementById('studentForm').onsubmit=async e=>{e.preventDefault();const body={teacher_id:S.user.id,name:document.getElementById('stName').value.trim(),grade:Number(document.getElementById('stGrade').value),access_token:token()};const {error}=await sb.from('students').insert(body);if(error)return fail(error);await loadTeacher();renderStudents();toast('Ученик создан')};
  document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{S.selectedStudent=b.dataset.profile;S.view='profile';renderTeacher()});
  document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const st=S.students.find(x=>x.id===b.dataset.copy);await copyText(studentLink(st));toast('Ссылка скопирована')});
  document.querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>{S.selectedStudent=b.dataset.board;S.view='board';renderTeacher()});
  document.querySelectorAll('[data-rotate]').forEach(b=>b.onclick=async()=>{if(!confirm('Старая ссылка перестанет работать. Продолжить?'))return;const {error}=await sb.rpc('rotate_student_access',{p_student_id:b.dataset.rotate});if(error)return fail(error);await loadTeacher();renderStudents();toast('Новая ссылка создана')});
  document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить ученика и его данные?'))return;const {error}=await sb.from('students').delete().eq('id',b.dataset.delete);if(error)return fail(error);await loadTeacher();renderStudents()});
}

async function profileAnalytics(studentId){
  const hs=S.homeworks.filter(x=>x.student_id===studentId),ts=S.tests.filter(x=>x.student_id===studentId),ls=S.lessons.filter(x=>x.student_id===studentId);
  const idsH=hs.map(x=>x.id),idsT=ts.map(x=>x.id);let items=[];
  if(idsH.length){const {data}=await sb.from('homework_items').select('homework_id,is_correct,category,tags,difficulty').in('homework_id',idsH);items.push(...(data||[]))}
  if(idsT.length){const {data}=await sb.from('test_items').select('test_id,is_correct,category,tags,difficulty').in('test_id',idsT);items.push(...(data||[]))}
  const cats={};for(const x of items.filter(x=>x.is_correct!==null)){const key=x.category||'Без категории';cats[key]??={ok:0,total:0};cats[key].total++;if(x.is_correct)cats[key].ok++}
  const weak=Object.entries(cats).map(([name,v])=>({name,score:Math.round(v.ok*100/v.total),total:v.total})).sort((a,b)=>a.score-b.score).slice(0,5);
  return {hs,ts,ls,weak,avgHw:avg(hs.map(x=>x.score)),avgTest:avg(ts.map(x=>x.score)),completed:ls.filter(x=>x.status==='completed').length};
}
async function renderStudentProfile(studentId){
  const st=S.students.find(x=>x.id===studentId);if(!st){S.view='students';return renderTeacher()}
  const a=await profileAnalytics(studentId);const upcoming=S.lessons.filter(x=>x.student_id===studentId&&x.status==='assigned'&&x.scheduled_at&&new Date(x.scheduled_at)>new Date()).slice(0,3);
  const recommendations=a.weak.flatMap(w=>S.exercises.filter(e=>e.kind==='task'&&e.category===w.name)).sort((x,y)=>(x.use_count||0)-(y.use_count||0)).slice(0,5);
  app.innerHTML=shell(`<div class="actions" style="margin-bottom:14px"><button class="btn" id="backStudents">← Ученики</button><button class="btn" id="profileBoard">Доска</button><button class="btn" id="profileLink">Скопировать ссылку</button></div><div class="card student-profile-head"><div><span class="pill">${st.grade} класс</span><h2>${esc(st.name)}</h2></div><div class="profile-edit"><input id="profileName" value="${esc(st.name)}"><select id="profileGrade">${Array.from({length:11},(_,i)=>`<option ${i+1===st.grade?'selected':''}>${i+1}</option>`).join('')}</select><button class="btn sm" id="saveProfile">Сохранить</button></div></div><div class="grid cols4 profile-metrics"><div class="card"><div class="muted">Уроков завершено</div><div class="metric">${a.completed}</div></div><div class="card"><div class="muted">Средняя домашняя</div><div class="metric">${a.avgHw==null?'—':a.avgHw+'%'}</div></div><div class="card"><div class="muted">Средний тест</div><div class="metric">${a.avgTest==null?'—':a.avgTest+'%'}</div></div><div class="card"><div class="muted">Новых заданий</div><div class="metric">${a.hs.filter(x=>x.status==='assigned').length+a.ts.filter(x=>x.status==='assigned').length}</div></div></div><div class="grid cols2" style="margin-top:16px"><div class="card"><h2>Слабые категории</h2>${a.weak.length?a.weak.map(w=>`<div class="progress-row"><div class="progress-head"><b>${esc(w.name)}</b><b>${w.score}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${w.score}%"></div></div><div class="small muted">${w.total} проверенных задач</div></div>`).join(''):'<div class="empty">Статистика появится после выполненных работ.</div>'}</div><div class="card"><h2>Рекомендации на следующий урок</h2>${recommendations.length?recommendations.map(e=>`<div class="item-box"><b>${esc(e.title||'Задача')}</b><div class="small muted">${esc(e.category||'')} · ${diffLabel(e.difficulty)}</div><div class="prewrap">${nl(e.content)}</div></div>`).join(''):'<div class="empty">Пока нет данных для рекомендаций.</div>'}</div></div><div class="section-title"><h2>Ближайшие уроки</h2></div><div class="list">${upcoming.length?upcoming.map(l=>`<div class="row"><div><h3>${esc(l.topics?.title||'Урок')}</h3><p>${dateLong(l.scheduled_at)}</p></div></div>`).join(''):'<div class="empty">Нет запланированных уроков.</div>'}</div>`,'Профиль ученика','Прогресс считается по реальным ответам');bindShell();
  document.getElementById('backStudents').onclick=()=>{S.view='students';renderTeacher()};document.getElementById('profileBoard').onclick=()=>{S.view='board';renderTeacher()};document.getElementById('profileLink').onclick=async()=>{await copyText(studentLink(st));toast('Ссылка скопирована')};
  document.getElementById('saveProfile').onclick=async()=>{const {error}=await sb.from('students').update({name:document.getElementById('profileName').value.trim(),grade:Number(document.getElementById('profileGrade').value)}).eq('id',st.id);if(error)return fail(error);await loadTeacher();renderStudentProfile(st.id);toast('Профиль сохранён')};
}

function renderTopics(){
  app.innerHTML=shell(`<div class="form-card"><h2>Новая тема</h2><form id="topicForm"><div class="grid cols3"><div class="field"><label>Класс</label><select id="tpGrade">${Array.from({length:11},(_,i)=>`<option>${i+1}</option>`).join('')}</select></div><div class="field"><label>Раздел</label><input id="tpSection" placeholder="Алгебра"></div><div class="field"><label>Тема</label><input id="tpTitle" required placeholder="Квадратные уравнения"></div></div><div class="field"><label>Теория</label><textarea id="tpTheory" rows="5"></textarea></div><button class="btn primary">Создать тему</button></form></div><div class="grid cols2">${S.topics.length?S.topics.map(t=>`<div class="card topic-card" data-topic="${t.id}"><span class="pill">${t.grade} класс</span><h3>${esc(t.title)}</h3><p>${esc(t.section||'Без раздела')}</p></div>`).join(''):'<div class="empty">Тем пока нет.</div>'}</div>`,'Темы','Теория, примеры, задачи и выдача работ');bindShell();
  document.getElementById('topicForm').onsubmit=async e=>{e.preventDefault();const {error}=await sb.from('topics').insert({teacher_id:S.user.id,grade:Number(document.getElementById('tpGrade').value),section:document.getElementById('tpSection').value.trim(),title:document.getElementById('tpTitle').value.trim(),theory:document.getElementById('tpTheory').value});if(error)return fail(error);await loadTeacher();renderTopics()};
  document.querySelectorAll('[data-topic]').forEach(x=>x.onclick=()=>{S.topic=S.topics.find(t=>t.id===x.dataset.topic);renderTopic()});
}
async function createAssignment(kind,studentId,topicId,count){
  const tasks=shuffle(S.exercises.filter(x=>x.topic_id===topicId&&x.kind==='task'&&x.answer.trim())).slice(0,count);if(!tasks.length)return toast('В теме нет задач с заполненными ответами');
  const t=S.topics.find(x=>x.id===topicId),base={teacher_id:S.user.id,student_id:studentId,topic_id:topicId,title:`${kind==='homework'?'Домашняя работа':'Мини-тест'} · ${t?.title||''}`};
  const table=kind==='homework'?'homeworks':'tests',itemsTable=kind==='homework'?'homework_items':'test_items';
  const {data:parent,error}=await sb.from(table).insert(base).select().single();if(error)return fail(error);
  const rows=tasks.map((x,i)=>({[kind==='homework'?'homework_id':'test_id']:parent.id,prompt:x.content,correct_answer:x.answer,position:i,source_exercise_id:x.id,difficulty:x.difficulty,category:x.category||'',tags:x.tags||[]}));
  const {error:e2}=await sb.from(itemsTable).insert(rows);if(e2)return fail(e2);await loadTeacher();toast(kind==='homework'?'Домашняя назначена':'Тест назначен');
}
function renderTopic(){
  const t=S.topic,items=S.exercises.filter(x=>x.topic_id===t.id),tasks=items.filter(x=>x.kind==='task'),examples=items.filter(x=>x.kind==='example');
  const studentOpts=S.students.map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.grade} кл.</option>`).join('');
  app.innerHTML=shell(`<div class="actions" style="margin-bottom:14px"><button class="btn" id="backTopics">← Темы</button><button class="btn primary" id="startLesson">Начать урок</button><select id="assignStudent" class="search" style="width:auto">${studentOpts}</select><input id="assignCount" class="search" type="number" min="1" max="20" value="5" style="width:80px"><button class="btn" id="makeHw">+ Домашняя</button><button class="btn" id="makeTest">+ Тест</button></div><div class="card"><span class="pill">${t.grade} класс · ${esc(t.section)}</span><h2>${esc(t.title)}</h2><div class="prewrap">${nl(t.theory||'Теория пока не добавлена')}</div></div><div class="section-title"><h2>Примеры</h2></div><div class="list">${examples.map(x=>`<div class="row"><div><h3>${esc(x.title||'Пример')}</h3><div class="prewrap">${nl(x.content)}</div></div></div>`).join('')||'<div class="empty">Нет примеров.</div>'}</div><div class="form-card"><h2>Добавить материал</h2><form id="itemForm"><div class="grid cols3"><div class="field"><label>Тип</label><select id="itKind"><option value="task">Задача</option><option value="example">Пример</option></select></div><div class="field"><label>Сложность</label><select id="itDiff"><option value="basic">Базовая</option><option value="medium">Средняя</option><option value="advanced">Сложная</option></select></div><div class="field"><label>Категория</label><input id="itCat"></div></div><div class="field"><label>Название</label><input id="itTitle"></div><div class="field"><label>Условие</label><textarea id="itContent" rows="4" required></textarea></div><div class="grid cols2"><div class="field"><label>Ответ</label><input id="itAnswer"></div><div class="field"><label>Теги через запятую</label><input id="itTags"></div></div><button class="btn primary">Добавить</button></form></div><div class="section-title"><h2>Задачи</h2></div><div class="list">${tasks.length?tasks.map(x=>`<div class="row"><div class="row-main"><div class="actions"><span class="pill">${diffLabel(x.difficulty)}</span>${x.category?`<span class="pill">${esc(x.category)}</span>`:''}</div><h3>${esc(x.title||'Задача')}</h3><div class="prewrap">${nl(x.content)}</div><div class="small muted">Ответ: ${esc(x.answer||'—')} · ${(x.tags||[]).map(z=>'#'+esc(z)).join(' ')}</div></div><button class="btn sm danger" data-del-task="${x.id}">Удалить</button></div>`).join(''):'<div class="empty">Задач пока нет.</div>'}</div>`,'Тема',`${t.grade} класс · ${t.section}`);bindShell();
  document.getElementById('backTopics').onclick=()=>{S.topic=null;S.view='topics';renderTeacher()};
  document.getElementById('itemForm').onsubmit=async e=>{e.preventDefault();const {error}=await sb.from('exercises').insert({teacher_id:S.user.id,topic_id:t.id,kind:document.getElementById('itKind').value,title:document.getElementById('itTitle').value.trim(),content:document.getElementById('itContent').value,answer:document.getElementById('itAnswer').value,difficulty:document.getElementById('itDiff').value,category:document.getElementById('itCat').value.trim(),tags:document.getElementById('itTags').value.split(',').map(x=>x.trim()).filter(Boolean)});if(error)return fail(error);await loadTeacher();S.topic=S.topics.find(x=>x.id===t.id);renderTopic()};
  document.querySelectorAll('[data-del-task]').forEach(b=>b.onclick=async()=>{await sb.from('exercises').delete().eq('id',b.dataset.delTask);await loadTeacher();S.topic=S.topics.find(x=>x.id===t.id);renderTopic()});
  document.getElementById('startLesson').onclick=async()=>{if(!S.students.length)return toast('Сначала добавь ученика');S.selectedStudent=document.getElementById('assignStudent').value||S.students[0].id;await startLesson(null,t.id,S.selectedStudent)};
  document.getElementById('makeHw').onclick=()=>createAssignment('homework',document.getElementById('assignStudent').value,t.id,Number(document.getElementById('assignCount').value));
  document.getElementById('makeTest').onclick=()=>createAssignment('test',document.getElementById('assignStudent').value,t.id,Number(document.getElementById('assignCount').value));
}

function renderBank(){
  const cats=[...new Set(S.exercises.map(x=>x.category).filter(Boolean))].sort(),tags=[...new Set(S.exercises.flatMap(x=>x.tags||[]))].sort();
  app.innerHTML=shell(`<div class="form-card"><div class="grid cols4"><div class="field"><label>Поиск</label><input id="bankSearch" placeholder="условие, тег, тема..."></div><div class="field"><label>Сложность</label><select id="bankDiff"><option value="">Все</option><option value="basic">Базовые</option><option value="medium">Средние</option><option value="advanced">Сложные</option></select></div><div class="field"><label>Категория</label><select id="bankCat"><option value="">Все</option>${cats.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Тег</label><select id="bankTag"><option value="">Все</option>${tags.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></div></div><div id="bankList"></div>`,'Банк задач','Категории, теги и история использования');bindShell();
  const draw=()=>{const qv=document.getElementById('bankSearch').value.toLowerCase(),d=document.getElementById('bankDiff').value,c=document.getElementById('bankCat').value,tag=document.getElementById('bankTag').value;const arr=S.exercises.filter(x=>x.kind==='task').filter(x=>(!d||x.difficulty===d)&&(!c||x.category===c)&&(!tag||(x.tags||[]).includes(tag))&&(!qv||[x.title,x.content,x.category,...(x.tags||[])].join(' ').toLowerCase().includes(qv)));document.getElementById('bankList').innerHTML=`<div class="list">${arr.length?arr.map(x=>{const t=S.topics.find(z=>z.id===x.topic_id);return `<div class="row"><div><div class="actions"><span class="pill">${t?.grade||'?'} кл.</span><span class="pill">${diffLabel(x.difficulty)}</span>${x.category?`<span class="pill">${esc(x.category)}</span>`:''}</div><h3>${esc(x.title||'Задача')}</h3><div class="prewrap">${nl(x.content)}</div><p>${esc(t?.title||'')} ${(x.tags||[]).map(z=>'#'+esc(z)).join(' ')} · использована ${x.use_count||0} раз</p></div><button class="btn sm" data-answer="${x.id}">Ответ</button></div>`}).join(''):'<div class="empty">Ничего не найдено.</div>'}</div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const e=S.exercises.find(x=>x.id===b.dataset.answer);modal(`<h2>${esc(e.title||'Ответ')}</h2><div class="notice mono">${esc(e.answer||'Ответ не заполнен')}</div>`)})};
  ['bankSearch','bankDiff','bankCat','bankTag'].forEach(id=>document.getElementById(id).oninput=draw);draw();
}

function renderSchedule(){
  const optsStudents=S.students.map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.grade} кл.</option>`).join(''),optsTopics=S.topics.map(t=>`<option value="${t.id}">${t.grade} кл. · ${esc(t.title)}</option>`).join('');
  app.innerHTML=shell(`<div class="form-card"><h2>Добавить урок</h2><form id="lessonForm" class="schedule-form"><div class="field"><label>Ученик</label><select id="lsStudent">${optsStudents}</select></div><div class="field"><label>Тема</label><select id="lsTopic">${optsTopics}</select></div><div class="field"><label>Дата и время</label><input id="lsWhen" type="datetime-local" required></div><div class="field"><label>Минут</label><input id="lsDuration" type="number" value="60" min="15" step="5"></div><button class="btn primary">Добавить</button></form></div><div class="list">${S.lessons.length?S.lessons.map(l=>`<div class="row"><div><h3>${esc(l.students?.name||'')} · ${esc(l.topics?.title||'Без темы')}</h3><p>${dateLong(l.scheduled_at)} · ${l.duration_minutes} мин · <span class="pill ${statusClass(l.status)}">${statusLabel(l.status)}</span></p></div><div class="actions">${l.status!=='completed'?`<button class="btn sm primary" data-open-lesson="${l.id}">${l.status==='in_progress'?'Продолжить':'Начать'}</button>`:''}<button class="btn sm danger" data-del-lesson="${l.id}">Удалить</button></div></div>`).join(''):'<div class="empty">Уроков пока нет.</div>'}</div>`,'Расписание','План занятий хранится в Supabase');bindShell();
  document.getElementById('lessonForm').onsubmit=async e=>{e.preventDefault();if(!document.getElementById('lsStudent').value||!document.getElementById('lsTopic').value)return toast('Добавь ученика и тему');const {error}=await sb.from('lessons').insert({teacher_id:S.user.id,student_id:document.getElementById('lsStudent').value,topic_id:document.getElementById('lsTopic').value,scheduled_at:new Date(document.getElementById('lsWhen').value).toISOString(),duration_minutes:Number(document.getElementById('lsDuration').value)});if(error)return fail(error);await loadTeacher();renderSchedule()};
  document.querySelectorAll('[data-open-lesson]').forEach(b=>b.onclick=async()=>startLesson(S.lessons.find(x=>x.id===b.dataset.openLesson)));
  document.querySelectorAll('[data-del-lesson]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить урок?'))return;await sb.from('lessons').delete().eq('id',b.dataset.delLesson);await loadTeacher();renderSchedule()});
}

async function openTeacherAssignment(kind,id){
  const table=kind==='homework'?'homeworks':'tests',itemsTable=kind==='homework'?'homework_items':'test_items',fk=kind==='homework'?'homework_id':'test_id';
  const parent=(kind==='homework'?S.homeworks:S.tests).find(x=>x.id===id);const {data:items,error}=await sb.from(itemsTable).select('*').eq(fk,id).order('position');if(error)return fail(error);
  const html=`<h2>${esc(parent.title)}</h2><p class="muted">${esc(parent.students?.name||'')} · ${esc(parent.topics?.title||'')} · ${statusLabel(parent.status)}${parent.score!=null?` · ${parent.score}%`:''}</p><div class="answers">${(items||[]).map((x,i)=>`<div class="answer-item ${x.is_correct===true?'correct':x.is_correct===false?'wrong':''}"><b>${i+1}. ${esc(x.prompt)}</b><div class="small">Ответ ученика: <b>${esc(x.student_answer||'—')}</b></div><div class="small muted">Правильный: ${esc(x.correct_answer||'—')}</div></div>`).join('')}</div>${kind==='homework'?`<div class="field"><label>Комментарий ученику</label><textarea id="reviewComment">${esc(parent.comment||'')}</textarea></div><button class="btn primary" id="saveReview">Сохранить проверку</button>`:''}`;
  const m=modal(html);if(kind==='homework')m.querySelector('#saveReview').onclick=async()=>{const {error}=await sb.from('homeworks').update({comment:m.querySelector('#reviewComment').value,status:'reviewed'}).eq('id',id);if(error)return fail(error);m.remove();await loadTeacher();renderAssignments();toast('Проверка сохранена')};
}
function renderAssignments(){
  const h=S.homeworks.map(x=>({...x,kind:'homework'})),t=S.tests.map(x=>({...x,kind:'test'})),all=[...h,...t].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));
  app.innerHTML=shell(`<div class="list">${all.length?all.map(x=>`<div class="row assignment"><div><h3>${x.kind==='homework'?'Домашняя':'Тест'} · ${esc(x.title)}</h3><p>${esc(x.students?.name||'')} · ${esc(x.topics?.title||'')} · ${dateShort(x.created_at)}</p><span class="pill ${statusClass(x.status)}">${statusLabel(x.status)}</span>${x.score!=null?` <span class="pill">${x.score}%</span>`:''}</div><button class="btn sm" data-assignment="${x.kind}:${x.id}">Открыть</button></div>`).join(''):'<div class="empty">Заданий пока нет.</div>'}</div>`,'Задания','Ответы учеников и проверка');bindShell();
  document.querySelectorAll('[data-assignment]').forEach(b=>b.onclick=()=>{const[k,id]=b.dataset.assignment.split(':');openTeacherAssignment(k,id)});
}

async function saveSnapshot(lesson,title='Итог урока',note=''){
  if(S.boardController?.save) await S.boardController.save();
  const {data:pages,error}=await sb.from('board_pages').select('id,title,sort_order,elements').eq('student_id',lesson.student_id).order('sort_order');if(error)throw error;
  const {error:e2}=await sb.from('lesson_board_versions').insert({teacher_id:S.user.id,lesson_id:lesson.id,title,note,pages:pages||[]});if(e2)throw e2;
}
function renderHistory(){
  const all=S.lessons.filter(x=>x.status==='completed').sort((a,b)=>String(b.completed_at||b.created_at).localeCompare(String(a.completed_at||a.created_at)));
  app.innerHTML=shell(`<div class="list">${all.length?all.map(l=>`<div class="row"><div><h3>${esc(l.students?.name||'')} · ${esc(l.topics?.title||'')}</h3><p>${dateLong(l.completed_at||l.started_at)}${l.public_summary?` · ${esc(l.public_summary.slice(0,120))}`:''}</p></div><button class="btn sm" data-history="${l.id}">Открыть</button></div>`).join(''):'<div class="empty">Завершённых уроков пока нет.</div>'}</div>`,'История уроков','Итоги и сохранённые версии доски');bindShell();document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>openHistoryLesson(b.dataset.history));
}
async function openHistoryLesson(id){
  const l=S.lessons.find(x=>x.id===id),versions=S.versions.filter(x=>x.lesson_id===id);const m=modal(`<h2>${esc(l.students?.name||'')} · ${esc(l.topics?.title||'')}</h2><div class="grid cols2"><div class="notice"><b>Итоги ученику</b><div class="prewrap">${nl(l.public_summary||'—')}</div></div><div class="notice"><b>К следующему уроку</b><div class="prewrap">${nl(l.homework_plan||'—')}</div></div></div><div class="notice"><b>Приватные заметки</b><div class="prewrap">${nl(l.private_notes||'—')}</div></div><h3>Версии доски</h3><div class="list">${versions.length?versions.map(v=>`<div class="row"><div><b>${esc(v.title)}</b><div class="small muted">${dateLong(v.created_at)}${v.note?' · '+esc(v.note):''}</div></div><button class="btn sm" data-version="${v.id}">Открыть</button></div>`).join(''):'<div class="empty">Версий доски нет.</div>'}</div>`,'wide-modal');
  m.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{const v=versions.find(x=>x.id===b.dataset.version);m.remove();const x=modal(`<h2>${esc(v.title)}</h2><p class="muted">${esc(v.note||'Сохранённая версия')}</p><div id="snapshotRoot"></div>`,'snapshot-modal');mountSnapshot(x.querySelector('#snapshotRoot'),v.pages||[])});
}

async function startLesson(existing=null,topicId=null,studentId=null){
  let l=existing;
  if(!l){const sid=studentId||S.selectedStudent||S.students[0]?.id,tid=topicId||S.topic?.id||S.topics[0]?.id;if(!sid||!tid)return toast('Нужны ученик и тема');const {data,error}=await sb.from('lessons').insert({teacher_id:S.user.id,student_id:sid,topic_id:tid,status:'in_progress',started_at:new Date().toISOString()}).select('*,students(name,grade),topics(title)').single();if(error)return fail(error);l=data;await loadTeacher();}
  else if(l.status!=='in_progress'){const {data,error}=await sb.from('lessons').update({status:'in_progress',started_at:l.started_at||new Date().toISOString()}).eq('id',l.id).select('*,students(name,grade),topics(title)').single();if(error)return fail(error);l=data;await loadTeacher()}
  S.activeLesson=l;S.selectedStudent=l.student_id;S.topic=S.topics.find(x=>x.id===l.topic_id)||S.topic;S.view='lesson';renderTeacher();
}
async function ensureLiveState(lesson){
  const {data,error}=await sb.from('lesson_live_state').upsert({lesson_id:lesson.id,teacher_id:S.user.id,student_id:lesson.student_id},{onConflict:'lesson_id'}).select().single();if(error)throw error;return data;
}
function elapsedSeconds(live){let n=live?.timer_elapsed_seconds||0;if(live?.timer_running&&live.timer_started_at)n+=Math.max(0,Math.floor((Date.now()-new Date(live.timer_started_at).getTime())/1000));return n}
function fmtTime(s){s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
async function renderLesson(){
  const lesson=S.activeLesson||S.lessons.find(x=>x.status==='in_progress'&&x.student_id===S.selectedStudent&&x.topic_id===S.topic?.id);if(!lesson){S.view='dashboard';return renderTeacher()}
  S.activeLesson=lesson;const st=S.students.find(x=>x.id===lesson.student_id),t=S.topics.find(x=>x.id===lesson.topic_id);if(!st||!t){S.view='dashboard';return renderTeacher()}
  const [{data:queue,error:qErr},live]=await Promise.all([sb.from('lesson_queue_items').select('*').eq('lesson_id',lesson.id).order('position'),ensureLiveState(lesson)]);if(qErr)return fail(qErr);
  const items=S.exercises.filter(x=>x.topic_id===t.id),tasks=items.filter(x=>x.kind==='task'),examples=items.filter(x=>x.kind==='example');let liveState=live,current=(queue||[]).find(x=>x.id===liveState.current_queue_item_id)||null;
  const queueHtml=(queue||[]).length?(queue||[]).map((x,i)=>`<div class="lesson-queue-row ${current?.id===x.id?'current':''} status-${x.status}"><button class="queue-select" data-current="${x.id}"><span class="queue-status">${x.status==='solved'?'✓':x.status==='hard'?'!':x.status==='later'?'↩':'○'}</span><span><b>${i+1}. ${esc(x.title||'Задача')}</b><small>${esc(x.prompt)}</small></span></button><button class="icon-btn" data-remove-queue="${x.id}">×</button></div>`).join(''):'<div class="small muted">Очередь пока пустая.</div>';
  app.innerHTML=shell(`<div class="actions" style="margin-bottom:12px"><button class="btn" id="leaveLesson">← Кабинет</button><button class="btn" id="copyLessonLink">Ссылка ученика</button><button class="btn" id="saveVersion">Сохранить версию доски</button><button class="btn primary" id="completeLesson">Завершить урок</button></div><div class="lesson-live-card" id="lessonControl"><div class="lesson-live-top"><div class="lesson-timer-block"><span class="muted">Время урока</span><span class="lesson-timer" id="lessonTimer">${fmtTime(elapsedSeconds(liveState))}</span></div><div class="actions"><button class="btn sm" id="timerToggle">${liveState.timer_running?'Пауза':'Старт'}</button><button class="btn sm" id="timerReset">Сброс</button><button class="btn sm ${liveState.focus_enabled?'active':''}" id="focusToggle">Фокус ученика: ${liveState.focus_enabled?'вкл':'выкл'}</button></div></div><div class="lesson-current-task"><div class="lesson-task-kicker">Текущая задача</div>${current?`<h3>${esc(current.title)}</h3><div class="lesson-task-prompt">${nl(current.prompt)}</div><div class="small muted lesson-answer">Ответ: ${esc(current.correct_answer||'—')}</div>`:'<div class="muted">Выбери задачу из очереди.</div>'}</div>${current?`<div class="lesson-task-status-actions"><button class="btn sm ${current.status==='solved'?'active':''}" data-status="solved">✓ Решено</button><button class="btn sm ${current.status==='hard'?'warn':''}" data-status="hard">⚠ Сложно</button><button class="btn sm ${current.status==='later'?'active':''}" data-status="later">↩ Вернуться позже</button><button class="btn sm" id="currentToBoard">На доску</button><button class="btn sm" id="currentToHomework">→ В домашнюю</button>${current.homework_added?'<span class="small homework-added">✓ Уже в домашней</span>':''}</div>`:''}<details class="lesson-queue" open><summary><b>Очередь на сегодня</b><span class="pill">${(queue||[]).length}</span></summary><div class="lesson-queue-list">${queueHtml}</div></details></div><div class="lesson-cloud-layout" style="margin-top:12px"><div class="lesson-cloud-material"><div class="card"><span class="pill">${t.grade} класс · ${esc(t.section)}</span><h2>${esc(t.title)}</h2><div class="prewrap">${nl(t.theory)}</div><button class="btn sm" id="theoryBoard">Теорию на доску</button></div><h3>Примеры</h3>${examples.map(x=>`<div class="item-box"><b>${esc(x.title||'Пример')}</b><div class="prewrap">${nl(x.content)}</div><button class="btn sm" data-to-board="${x.id}">На доску</button></div>`).join('')||'<div class="muted">Нет примеров</div>'}<h3>Задачи</h3>${tasks.map(x=>`<div class="item-box"><div class="actions" style="justify-content:space-between"><b>${esc(x.title||'Задача')}</b><span class="pill">${diffLabel(x.difficulty)}</span></div><div class="prewrap">${nl(x.content)}</div><div class="actions"><button class="btn sm" data-queue-task="${x.id}">+ В очередь</button><button class="btn sm" data-focus-task="${x.id}">В фокус</button><button class="btn sm" data-to-board="${x.id}">На доску</button></div></div>`).join('')||'<div class="muted">Нет задач</div>'}</div><div><div id="lessonBoard"></div></div></div>`,'Урок',`${st.name} · ${t.title}`);bindShell();
  let ctrl=await mountBoard(document.getElementById('lessonBoard'),st.id,true);S.boardController=ctrl;
  const updateLive=async patch=>{const {data,error}=await sb.from('lesson_live_state').update({...patch,updated_at:new Date().toISOString()}).eq('lesson_id',lesson.id).select().single();if(error)return fail(error);liveState=data;};
  const setCurrent=async q=>{await updateLive({current_queue_item_id:q?.id||null,current_title:q?.title||'',current_prompt:q?.prompt||'',current_position:q?.position||0});renderLesson()};
  const addQueue=async(exercise,makeCurrent=false)=>{const existing=(queue||[]).find(x=>x.exercise_id===exercise.id);let q=existing;if(!q){const {data,error}=await sb.from('lesson_queue_items').insert({teacher_id:S.user.id,lesson_id:lesson.id,exercise_id:exercise.id,title:exercise.title||'Задача',prompt:exercise.content,correct_answer:exercise.answer,difficulty:exercise.difficulty,category:exercise.category||'',tags:exercise.tags||[],position:(queue||[]).length}).select().single();if(error)return fail(error);q=data}if(makeCurrent)await setCurrent(q);else{toast('Добавлено в очередь');renderLesson()}};
  document.getElementById('leaveLesson').onclick=()=>{S.activeLesson=null;S.view='dashboard';renderTeacher()};document.getElementById('copyLessonLink').onclick=async()=>{await copyText(studentLink(st));toast('Ссылка скопирована')};document.getElementById('theoryBoard').onclick=()=>ctrl.addText(`${t.title}\n\n${t.theory}`,{fontSize:24});
  document.querySelectorAll('[data-to-board]').forEach(b=>b.onclick=()=>{const x=S.exercises.find(z=>z.id===b.dataset.toBoard);ctrl.addText(`${x.title||'Задача'}\n${x.content}`,{fontSize:25});sb.from('exercises').update({use_count:(x.use_count||0)+1,last_used_at:new Date().toISOString()}).eq('id',x.id).then(()=>{})});
  document.querySelectorAll('[data-queue-task]').forEach(b=>b.onclick=()=>addQueue(S.exercises.find(x=>x.id===b.dataset.queueTask),false));document.querySelectorAll('[data-focus-task]').forEach(b=>b.onclick=()=>addQueue(S.exercises.find(x=>x.id===b.dataset.focusTask),true));
  document.querySelectorAll('[data-current]').forEach(b=>b.onclick=()=>setCurrent((queue||[]).find(x=>x.id===b.dataset.current)));document.querySelectorAll('[data-remove-queue]').forEach(b=>b.onclick=async()=>{await sb.from('lesson_queue_items').delete().eq('id',b.dataset.removeQueue);if(liveState.current_queue_item_id===b.dataset.removeQueue)await updateLive({current_queue_item_id:null,current_title:'',current_prompt:''});renderLesson()});
  document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{if(!current)return;await sb.from('lesson_queue_items').update({status:b.dataset.status}).eq('id',current.id);renderLesson()});
  if(current){document.getElementById('currentToBoard').onclick=()=>ctrl.addText(`${current.title}\n${current.prompt}`,{fontSize:25});document.getElementById('currentToHomework').onclick=async()=>{let hw=S.homeworks.find(x=>x.lesson_id===lesson.id&&x.status==='assigned');if(!hw){const {data,error}=await sb.from('homeworks').insert({teacher_id:S.user.id,student_id:st.id,topic_id:t.id,lesson_id:lesson.id,title:`Домашняя после урока · ${t.title}`}).select().single();if(error)return fail(error);hw=data}const {data:dup}=await sb.from('homework_items').select('id').eq('homework_id',hw.id).eq('source_queue_item_id',current.id).maybeSingle();if(!dup){const {error}=await sb.from('homework_items').insert({homework_id:hw.id,prompt:current.prompt,correct_answer:current.correct_answer,position:999,source_exercise_id:current.exercise_id,source_queue_item_id:current.id,difficulty:current.difficulty,category:current.category,tags:current.tags||[]});if(error)return fail(error)}await sb.from('lesson_queue_items').update({homework_added:true}).eq('id',current.id);await loadTeacher();renderLesson();toast('Добавлено в домашнюю')}}
  document.getElementById('focusToggle').onclick=async()=>{await updateLive({focus_enabled:!liveState.focus_enabled});renderLesson()};document.getElementById('timerToggle').onclick=async()=>{if(liveState.timer_running){const e=elapsedSeconds(liveState);await updateLive({timer_running:false,timer_started_at:null,timer_elapsed_seconds:e})}else await updateLive({timer_running:true,timer_started_at:new Date().toISOString()});renderLesson()};document.getElementById('timerReset').onclick=async()=>{await updateLive({timer_running:false,timer_started_at:null,timer_elapsed_seconds:0});renderLesson()};
  const interval=setInterval(()=>{const el=document.getElementById('lessonTimer');if(el)el.textContent=fmtTime(elapsedSeconds(liveState))},1000);S.liveCleanup=()=>clearInterval(interval);
  document.getElementById('saveVersion').onclick=async()=>{const title=prompt('Название версии:',`Версия · ${new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}`);if(title===null)return;const note=prompt('Заметка к версии:','')||'';try{await saveSnapshot(lesson,title||'Версия доски',note);await loadTeacher();toast('Версия сохранена')}catch(e){fail(e)}};
  document.getElementById('completeLesson').onclick=()=>completeLesson(lesson,queue||[],liveState);
}
async function completeLesson(lesson,queue,live){
  const counts={solved:queue.filter(x=>x.status==='solved').length,hard:queue.filter(x=>x.status==='hard').length,later:queue.filter(x=>x.status==='later').length,total:queue.length,hw:queue.filter(x=>x.homework_added).length};const mins=Math.round(elapsedSeconds(live)/60);
  const summary=`На уроке разобрали ${counts.total} задач. Решено: ${counts.solved}. Сложными отмечено: ${counts.hard}. Вернуться позже: ${counts.later}.`;
  const plan=`${counts.hw?`В домашнюю добавлено ${counts.hw} задач. `:''}${counts.later?`Вернуться к ${counts.later} отложенным задачам.`:'Закрепить материал по необходимости.'}`;
  const m=modal(`<h2>Завершить урок</h2><div class="lesson-report-preview"><div class="report-stats"><span>Задач: ${counts.total}</span><span>Решено: ${counts.solved}</span><span>Сложно: ${counts.hard}</span><span>Позже: ${counts.later}</span><span>Время: ${mins} мин</span></div></div><div class="field"><label>Итоги ученику</label><textarea id="finishSummary">${esc(summary)}</textarea></div><div class="field"><label>К следующему уроку</label><textarea id="finishPlan">${esc(plan)}</textarea></div><div class="field"><label>Приватная заметка</label><textarea id="finishPrivate">Очередь: ${counts.total}; решено: ${counts.solved}; сложно: ${counts.hard}; позже: ${counts.later}; таймер: ${mins} мин.</textarea></div><button class="btn primary" id="finishConfirm">Завершить и сохранить доску</button>`);
  m.querySelector('#finishConfirm').onclick=async()=>{try{await saveSnapshot(lesson,'Итог урока','Автоматически сохранено при завершении');const {error}=await sb.from('lessons').update({status:'completed',completed_at:new Date().toISOString(),public_summary:m.querySelector('#finishSummary').value,homework_plan:m.querySelector('#finishPlan').value,private_notes:m.querySelector('#finishPrivate').value}).eq('id',lesson.id);if(error)throw error;await sb.from('lesson_live_state').update({focus_enabled:false,timer_running:false,timer_started_at:null,timer_elapsed_seconds:elapsedSeconds(live)}).eq('lesson_id',lesson.id);m.remove();await loadTeacher();S.activeLesson=null;S.view='history';renderTeacher();toast('Урок завершён')}catch(e){fail(e)}};
}

function renderBoardPage(){
  if(!S.students.length){app.innerHTML=shell('<div class="empty">Сначала добавь ученика.</div>','Доска');bindShell();return}const st=S.students.find(x=>x.id===S.selectedStudent)||S.students[0];S.selectedStudent=st.id;
  app.innerHTML=shell(`<div class="actions" style="margin-bottom:12px"><select id="boardStudent" class="search">${S.students.map(s=>`<option value="${s.id}" ${s.id===st.id?'selected':''}>${esc(s.name)} · ${s.grade} кл.</option>`).join('')}</select></div><div id="boardRoot"></div>`,'Общая доска',`${st.name} · realtime через Supabase`);bindShell();document.getElementById('boardStudent').onchange=()=>{S.selectedStudent=document.getElementById('boardStudent').value;renderBoardPage()};mountBoard(document.getElementById('boardRoot'),st.id,true).then(c=>S.boardController=c);
}

async function bootStudent(){
  if(!configured)return configScreen();let {data:{session}}=await sb.auth.getSession();if(session&&!session.user.is_anonymous){app.innerHTML=`<div class="center-page"><div class="auth-card"><div class="brand">Mathroom</div><h1>Открой ссылку ученика отдельно</h1><p>В этом браузере уже выполнен вход преподавателя. Открой ссылку ученика в режиме инкогнито или на другом устройстве.</p></div></div>`;return}if(!session){const {data,error}=await sb.auth.signInAnonymously();if(error){app.innerHTML=`<div class="center-page"><div class="auth-card"><h1>Нужно включить Anonymous Sign-Ins</h1><p>${esc(error.message)}</p></div></div>`;return}session=data.session}
  const {data:claimed,error:claimErr}=await sb.rpc('claim_student_access',{p_token:S.access});if(claimErr){app.innerHTML=`<div class="center-page"><div class="auth-card"><div class="brand">Mathroom</div><h1>Ссылка недействительна</h1><p>Попроси преподавателя прислать новую ссылку.</p></div></div>`;return}const {data:student,error}=await sb.from('students').select('id,name,grade').eq('id',claimed.id).single();if(error)return fail(error);S.student=student;renderStudent();
}
async function getStudentData(){
  const [{data:lessons},{data:homeworks},{data:tests}]=await Promise.all([sb.from('lessons').select('*,topics(title)').eq('student_id',S.student.id).order('scheduled_at',{ascending:true}),sb.from('homeworks').select('id,title,status,score,comment,created_at,submitted_at,topics(title)').eq('student_id',S.student.id).order('created_at',{ascending:false}),sb.from('tests').select('id,title,status,score,created_at,submitted_at,topics(title)').eq('student_id',S.student.id).order('created_at',{ascending:false})]);
  return {lessons:lessons||[],homeworks:homeworks||[],tests:tests||[]};
}
async function currentStudentLive(lessons){
  const active=lessons.find(x=>x.status==='in_progress');if(!active)return {active:null,live:null};const {data}=await sb.from('lesson_live_state').select('*').eq('lesson_id',active.id).maybeSingle();return {active,live:data};
}
function studentLiveCard(active,live){if(!active||!live)return '';return `<div class="student-live-mount"><div class="lesson-live-card"><div class="lesson-live-top"><div><div class="lesson-task-kicker">Идёт урок</div><b>${esc(active.topics?.title||'Урок')}</b></div><div class="lesson-timer" id="studentTimer">${fmtTime(elapsedSeconds(live))}</div></div>${live.current_prompt?`<div class="lesson-current-task"><div class="lesson-task-kicker">Текущая задача</div><h3>${esc(live.current_title||'Задача')}</h3><div class="lesson-task-prompt">${nl(live.current_prompt)}</div></div>`:'<div class="notice">Преподаватель пока не выбрал текущую задачу.</div>'}</div></div>`}
async function renderStudent(){
  cleanupAll();const d=await getStudentData(),{active,live}=await currentStudentLive(d.lessons);S.studentLive=live;
  if(active&&live?.focus_enabled){app.innerHTML=`<div class="student-home student-focus">${studentLiveCard(active,live)}<div id="focusBoard"></div></div>`;await mountBoard(document.getElementById('focusBoard'),S.student.id,false);subscribeStudentLive(active.id);return}
  app.innerHTML=`<div class="student-home"><div class="student-top"><div><div class="brand">Mathroom</div><h1>${esc(S.student.name)}</h1><p class="muted">${S.student.grade} класс · персональный кабинет</p></div><div class="tabs"><button id="studentBoardTab" class="${S.studentTab==='board'?'active':''}">Доска</button><button id="studentTasksTab" class="${S.studentTab==='tasks'?'active':''}">Задания</button><button id="studentLessonsTab" class="${S.studentTab==='lessons'?'active':''}">Уроки</button></div></div>${studentLiveCard(active,live)}<div id="studentContent"></div></div>`;
  document.getElementById('studentBoardTab').onclick=()=>{S.studentTab='board';renderStudent()};document.getElementById('studentTasksTab').onclick=()=>{S.studentTab='tasks';renderStudent()};document.getElementById('studentLessonsTab').onclick=()=>{S.studentTab='lessons';renderStudent()};
  const c=document.getElementById('studentContent');if(S.studentTab==='lessons')c.innerHTML=`<div class="list">${d.lessons.length?d.lessons.map(l=>`<div class="row student-lesson"><div><h3>${esc(l.topics?.title||'Урок')}</h3><p>${dateLong(l.scheduled_at)} · ${l.duration_minutes} мин · ${statusLabel(l.status)}</p>${l.public_summary?`<div class="notice">${nl(l.public_summary)}</div>`:''}${l.homework_plan?`<div class="small"><b>К следующему уроку:</b> ${esc(l.homework_plan)}</div>`:''}</div></div>`).join(''):'<div class="empty">Уроков пока нет.</div>'}</div>`;
  else if(S.studentTab==='tasks'){const all=[...d.homeworks.map(x=>({...x,kind:'homework'})),...d.tests.map(x=>({...x,kind:'test'}))].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));c.innerHTML=`<div class="list">${all.length?all.map(x=>`<div class="row"><div><h3>${x.kind==='homework'?'Домашняя':'Тест'} · ${esc(x.title)}</h3><p>${esc(x.topics?.title||'')} · ${statusLabel(x.status)}${x.score!=null?` · ${x.score}%`:''}</p>${x.comment?`<div class="small muted">Комментарий: ${esc(x.comment)}</div>`:''}</div><button class="btn sm primary" data-student-assignment="${x.kind}:${x.id}">${x.status==='assigned'?'Выполнить':'Посмотреть'}</button></div>`).join(''):'<div class="empty">Заданий пока нет.</div>'}</div>`;c.querySelectorAll('[data-student-assignment]').forEach(b=>b.onclick=()=>openStudentAssignment(...b.dataset.studentAssignment.split(':')))}
  else await mountBoard(c,S.student.id,false);
  if(active)subscribeStudentLive(active.id);
}
function subscribeStudentLive(lessonId){
  cleanupLive();let timerInt=setInterval(()=>{const el=document.getElementById('studentTimer');if(el)el.textContent=fmtTime(elapsedSeconds(S.studentLive))},1000);const ch=sb.channel(`student-live:${lessonId}`).on('postgres_changes',{event:'UPDATE',schema:'public',table:'lesson_live_state',filter:`lesson_id=eq.${lessonId}`},payload=>{S.studentLive=payload.new;renderStudent()}).subscribe();S.liveCleanup=()=>{clearInterval(timerInt);sb.removeChannel(ch)};
}
async function openStudentAssignment(kind,id){
  const rpc=kind==='homework'?'get_student_homework':'get_student_test',arg=kind==='homework'?{p_homework_id:id}:{p_test_id:id};const {data,error}=await sb.rpc(rpc,arg);if(error)return fail(error);const assigned=data.status==='assigned';const m=modal(`<h2>${esc(data.title)}</h2>${data.score!=null?`<div class="score">${data.score}%</div>`:''}<form id="studentAnswerForm" class="answers">${(data.items||[]).map((x,i)=>`<div class="answer-item ${x.is_correct===true?'correct':x.is_correct===false?'wrong':''}"><b>${i+1}. ${esc(x.prompt)}</b><div class="field"><label>Ответ</label><input name="ans_${x.id}" value="${esc(x.student_answer||'')}" ${assigned?'':'disabled'}></div>${!assigned&&x.is_correct!==null?`<div class="small">${x.is_correct?'✓ Верно':'✕ Ошибка'}</div>`:''}</div>`).join('')}${assigned?'<button class="btn primary">Отправить</button>':''}</form>${data.comment?`<div class="notice"><b>Комментарий преподавателя</b><br>${nl(data.comment)}</div>`:''}`);if(assigned)m.querySelector('#studentAnswerForm').onsubmit=async e=>{e.preventDefault();const answers={};for(const x of data.items||[])answers[x.id]=m.querySelector(`[name="ans_${x.id}"]`).value;const submitRpc=kind==='homework'?'submit_homework':'submit_test',args=kind==='homework'?{p_homework_id:id,p_answers:answers}:{p_test_id:id,p_answers:answers};const {data:res,error:er}=await sb.rpc(submitRpc,args);if(er)return fail(er);toast(`Результат: ${res.score}%`);m.remove();renderStudent()};
}

window.addEventListener('mathroom:refresh-lesson',()=>{if(S.view==='lesson'&&S.activeLesson)renderLesson()});

boot().catch(e=>{console.error(e);app.innerHTML=`<div class="center-page"><div class="auth-card"><h1>Ошибка запуска</h1><p>${esc(e.message)}</p></div></div>`});
})();
